/** True only for calls whose first response the runtime durably replays. */
export type WireMutationMethodName = {
  [M in WireMethodName]: (typeof WIRE_METHOD_POLICY)[M]["operation"] extends "command"
    ? M
    : never;
}[WireMethodName];

export function wireMethodRequiresIdempotency(method: WireMethodName): boolean {
  return WIRE_METHOD_POLICY[method].operation === "command";
}

/** Every stream that accepts an opaque Run event replay cursor. */
export type WireReplayCursorMethodName = {
  [M in WireMethodName]: (typeof WIRE_METHOD_POLICY)[M]["replayCursor"] extends "run"
    ? M
    : never;
}[WireMethodName];

export function wireMethodAcceptsReplayCursor(
  method: WireMethodName,
): method is WireReplayCursorMethodName {
  return WIRE_METHOD_POLICY[method].replayCursor === "run";
}

/** Every cursor-paginated method, derived from the method policy above. */
export type WirePaginatedMethodName = {
  [M in WireMethodName]: (typeof WIRE_METHOD_POLICY)[M]["pagination"] extends "cursor"
    ? M
    : never;
}[WireMethodName];

export function wireMethodIsPaginated(
  method: WireMethodName,
): method is WirePaginatedMethodName {
  return WIRE_METHOD_POLICY[method].pagination === "cursor";
}

/** One condition on the request that decides whether a rule applies. */
export interface WireCapabilityCondition {
  field: string;
  operator: "present" | "equals";
  value?: string;
}

/**
 * What a method needs negotiated. An absent `when` gates the whole method; a
 * condition gates only the requests that match it.
 */
export interface WireCapabilityRule {
  when?: readonly WireCapabilityCondition[];
  requires: readonly WireFeature[];
}

